function updateStats(frame) {
  const key = hex(frame.id), previous = state.stats.get(key);
  if(state.frozenIds.has(key))return;
  const byteList = bytes(frame);
  const now=performance.now(),item = previous || { count: 0, valid: 0, totalDelta: 0, deltas: 0, dataTotalDelta: 0, dataDeltas: 0, lastTime: frame.time, lastDataChangeTime: frame.time, lastSeenAt: now, changed: [], byteChanges:Array(8).fill(0), byteFlashUntil:Array(8).fill(0), deltaMin:null, deltaMax:null, newUntil:now+900 };
  if (previous) { const delta=Math.max(0,frame.time-item.lastTime);item.totalDelta+=delta;item.deltas++;item.delta=delta;item.deltaMin=item.deltaMin===null?delta:Math.min(item.deltaMin,delta);item.deltaMax=item.deltaMax===null?delta:Math.max(item.deltaMax,delta);item.changed=byteList.map((byte,i)=>byte!==item.bytes?.[i]);if(item.changed.some(Boolean)){item.dataTotalDelta+=Math.max(0,frame.time-item.lastDataChangeTime);item.dataDeltas++;item.dataDelta=Math.max(0,frame.time-item.lastDataChangeTime);item.lastDataChangeTime=frame.time;item.lastChangeAt=now;}item.changed.forEach((changed,i)=>{if(changed){item.byteChanges[i]++;item.byteFlashUntil[i]=now+650;}}); }
  item.count++; item.valid += frame.valid ? 1 : 0; item.lastTime = frame.time; item.pid = frame.pid; item.length = frame.length; item.bytes = byteList; item.sequence = frame.sequence;
  item.source=frame.source||'LIN';item.lastSeenAt=now;item.packetFlashUntil=now+500;
  state.stats.set(key, item);
}

function ingest(frames, source = 'LIN') {
  const incoming = frames.filter(frame => source !== 'LIN' || frame.sequence > state.lastSequence).map(frame => ({...frame, source}));
  for (const frame of incoming) { updateStats(frame); if (state.logActive){const logged={...frame,capturedAt:Date.now(),session:state.logSession};state.log.push(logged);logPending.push(logged);} }
  if (incoming.length) { state.frames.push(...incoming); state.frames = state.frames.slice(-Math.max(state.rowLimit, 500)); state.lastSequence = Math.max(state.lastSequence, ...incoming.map(f => f.sequence)); }
  if (state.logActive && incoming.length&&logPending.length>=50)flushLog();
}

function renderMetrics(status = null) {
  const total = status ? Number(status.frames || 0) : state.frames.length;
  const valid = status ? Number(status.validFrames || 0) : state.frames.filter(f => f.valid).length;
  $('frames').textContent = total.toLocaleString('de-DE'); $('valid-frames').textContent = valid.toLocaleString('de-DE');
  $('header-frames').textContent = String(total).padStart(5,'0');
  $('invalid-frames').textContent = (status ? Number(status.invalidFrames || 0) : total - valid).toLocaleString('de-DE');
  $('valid-rate').textContent = `${total ? Math.round(valid * 100 / total) : 0}%`; $('active-ids').textContent = state.stats.size;
  if (status) { $('version').textContent = `V${status.version}`; $('baud').textContent = `${Number(status.baudrate).toLocaleString('de-DE')} bit/s`; if($('setting-checksum'))$('setting-checksum').value=status.checksumMode||'auto'; updateTxLock(); }
  if (status) {
    $('header-rate').textContent = `${status.frameRate || 0}/s`;
    $('header-queue').textContent = `${status.queue || 0}/${status.queueCapacity || 128} · ${status.queueUtilization || 0}%`;
    $('header-uart').textContent = `${status.uartBytes || 0} B`;
    $('header-drops').textContent = status.queueDrops || 0;
    $('header-heap').textContent = `${Math.round(Number(status.freeHeap || 0) / 1024)} kB`;
    $('queue-pill').classList.toggle('warning', Number(status.queueUtilization) >= 75);
    $('drop-pill').classList.toggle('error', Number(status.queueDrops) > 0);
    $('buffer-count').textContent = status.queue || 0;
    $('buffer-capacity').textContent = status.queueCapacity || 128;
  }
}

