function latestFor(id) { return [...state.frames].reverse().find(frame => hex(frame.id) === id); }
function decodeSignal(signal) { const frame = latestFor(signal.id); if (!frame) return '—'; const data = bytes(frame).map(x => parseInt(x,16));let packed=0n;data.forEach((value,index)=>packed|=BigInt(value)<<(BigInt(index)*8n));const start=BigInt(Number(signal.byte||0)*8+Number(signal.bit||0)),length=Math.max(1,Math.min(32,Number(signal.length)||1)),mask=(1n<<BigInt(length))-1n,raw=Number((packed>>start)&mask);return `${(raw * Number(signal.factor||1) + Number(signal.offset||0)).toFixed(2)} ${signal.unit||''}`.trim(); }
