function renderOverview(){if(document.querySelector('.rowActionMenu[open]')||document.activeElement?.matches('[data-label-edit]'))return;const now=performance.now(),query=$('overview-search')?.value.trim().toUpperCase()||'',windowMs=Number($('overview-window')?.value||2)*1000,fast=Number($('overview-fast-limit')?.value||100);let rows=[...state.stats.entries()].filter(([id,item])=>(!query||id.includes(query)||(state.labels[id]||'').toUpperCase().includes(query))&&(!state.overviewDecoded||isDecodedId(id))&&(!state.overviewHideFast||!item.dataDeltas||item.dataTotalDelta/item.dataDeltas>=fast)&&(!state.overviewChanged||!item.lastDataChangeTime||performance.now()-item.lastDataChangeTime<=windowMs));const value=([id,item],key)=>key==='label'?(state.labels[id]||'').toUpperCase():key==='frames'?item.count:key==='age'?now-Number(item.lastSeenAt||now):parseInt(id,16);rows.sort((a,b)=>{const av=value(a,state.overviewSort.key),bv=value(b,state.overviewSort.key);return(typeof av==='string'?av.localeCompare(bv):av-bv)*state.overviewSort.dir;});const body=$('overview-list'),current=[...body.querySelectorAll('.overview-row')],keys=rows.map(([id])=>id),same=current.length===keys.length&&current.every((row,index)=>row.dataset.overviewId===keys[index]);if(!rows.length)body.innerHTML=emptyRow(20,'Noch keine passenden LIN-IDs.');else if(!same)body.innerHTML=rows.map(([id,item])=>overviewRowHtml(id,item,now)).join('');else current.forEach((row,index)=>updateOverviewRow(row,rows[index][0],rows[index][1],now));$('overview-status-frames').textContent=state.frames.length;$('overview-status-ids').textContent=state.stats.size;$('overview-status-visible').textContent=rows.length;document.querySelectorAll('[data-overview-sort]').forEach(th=>{const active=th.dataset.overviewSort===state.overviewSort.key;th.classList.toggle('sort-active',active);th.setAttribute('aria-sort',active?(state.overviewSort.dir===1?'ascending':'descending'):'none');});}
