function renderLogs() { const duration=state.log.length>1?Math.max(0,(state.log.at(-1).time-state.log[0].time)/1000):0,size=new Blob([JSON.stringify(state.log)]).size; $('log-count').textContent = state.log.length.toLocaleString('de-DE');$('log-saved').textContent=Math.max(0,state.log.length-logPending.length).toLocaleString('de-DE');$('log-session').textContent=state.logSession||state.log.at(-1)?.session||'—'; $('log-state').textContent = state.logActive ? 'Aufzeichnung' : 'Bereit'; $('log-toggle').textContent = state.logActive ? 'Aufzeichnung stoppen' : 'Aufzeichnung starten'; $('log-toggle').classList.toggle('active', state.logActive); $('log-duration').textContent = state.logActive ? `${Math.round((Date.now()-state.logStart)/1000)} s` : `${duration.toFixed(1)} s`; $('log-size').textContent=size<1024?`${size} B`:`${(size/1024).toFixed(1)} kB`;$('log-source').textContent=state.importedLog.length?'Browser + Import':'Browser'; $('log-list').innerHTML = state.log.length ? state.log.slice(-250).reverse().map((f,i,rows) => {const next=rows[i+1],delta=next?Math.max(0,f.time-next.time):0;return `<tr><td>${state.log.length-i}</td><td>${new Date(f.capturedAt||Date.now()).toLocaleTimeString('de-DE')}</td><td>${delta.toFixed(0)} ms</td><td class="source-${esc(f.source||'LIN')}">${esc(f.source==='REPLAY'?'LOG':f.source||'LIN')}</td><td>${displayId(f.id)}</td><td>${hexDisplay(f.pid)}</td><td>${f.length}</td><td class="payload">${esc(f.data.split(' ').map(byteDisplay).join(' '))}</td><td>${hexDisplay(f.checksum)}</td><td>${f.valid?'OK':'Fehler'}</td></tr>`;}).join('') : emptyRow(10, 'Noch keine Frames aufgezeichnet.'); }
