function applyStatus(status) {latestStatus=status;updateLiveSourceUi();minFreeHeap=minFreeHeap===null?Number(status.freeHeap||0):Math.min(minFreeHeap,Number(status.freeHeap||0));renderMetrics(status);setConnection(true);$('diag-queue').textContent=`${status.queue||0} / ${status.queueCapacity||128}`;$('diag-high-water').textContent=status.queueHighWater||0;$('diag-drops').textContent=status.queueDrops||0;$('diag-uart').textContent=status.uartBytes||0;$('diag-rate').textContent=status.frameRate||0;$('diag-heap').textContent=`${status.freeHeap||0} B`;$('diag-last-frame').textContent=status.lastFrameAgoMs?`${status.lastFrameAgoMs} ms`:'—';if($('diag-min-heap'))$('diag-min-heap').textContent=`${minFreeHeap||0} B`;if($('diag-last-ws'))$('diag-last-ws').textContent=lastWsMessageAt?`${Date.now()-lastWsMessageAt} ms`:'—';$('status-dump').textContent=JSON.stringify(status,null,2);if(status.baudrate)$('setting-baud').value=String(status.baudrate);if($('wifi-ap-address'))$('wifi-ap-address').textContent=`${status.apSsid||'DEALS'} · ${status.apIp||'192.168.4.1'}`;if($('wifi-sta-status'))$('wifi-sta-status').textContent=status.staConnected?`Verbunden · ${status.staIp}`:status.staConfigured?'Konfiguriert · nicht verbunden':'Nicht konfiguriert';if(document.activeElement!==$('server-filter-ids')){$('server-filter-mode').value=status.filterMode||'exclude';$('server-filter-ids').value=load('idFormat','HEX')==='DEC'?String(status.filterIds||'').split(/\s+/).filter(Boolean).map(x=>parseInt(x,16)).join(' '):status.filterIds||'';}$('server-filter-apply').dataset.active=status.filterEnabled?'1':'0';$('server-filter-apply').textContent=status.filterEnabled?'Filter löschen':'Filter anwenden';$('server-filter-apply').classList.toggle('active',!!status.filterEnabled); }
function applyLiveFrame(frame) { ingest([frame]); if(!state.paused)queueRender(); }
async function loadSnapshot() { try { const [sr,fr]=await Promise.all([fetch('/api/status',{cache:'no-store'}),fetch('/api/frames',{cache:'no-store'})]); if(!sr.ok||!fr.ok)throw Error(); const [status,history]=await Promise.all([sr.json(),fr.json()]); ingest(history.frames||[]); applyStatus(status); renderAll(); } catch { if(!socketOpen)setConnection(false); } }
async function refresh() { if (!socketOpen) await loadSnapshot(); }
function connectWebSocket() {
  clearTimeout(reconnectTimer);
  if(document.hidden)return;
  const generation=++connectionGeneration;
  try { socket = new WebSocket(`ws://${location.hostname}:81/`); } catch { scheduleReconnect(); return; }
  const openTimeout=setTimeout(()=>{if(generation===connectionGeneration&&socket?.readyState!==WebSocket.OPEN)socket?.close();},5000);
  socket.onopen=()=>{if(generation!==connectionGeneration)return;clearTimeout(openTimeout);socketOpen=true;reconnectAttempt=0;lastWsMessageAt=Date.now();setConnection(true);loadSnapshot();};
  socket.onmessage=event=>{if(generation!==connectionGeneration)return;lastWsMessageAt=Date.now();try{const message=JSON.parse(event.data);if(message.type==='frame')applyLiveFrame(message.value);if(message.type==='status')applyStatus(message.value);}catch{}};
  socket.onclose=()=>{clearTimeout(openTimeout);if(generation!==connectionGeneration)return;socketOpen=false;setConnection(false);scheduleReconnect();};
  socket.onerror=()=>socket.close();
}
function scheduleReconnect(){if(reconnectTimer||document.hidden)return;const delays=[500,1000,2000,5000,10000],delay=delays[Math.min(reconnectAttempt++,delays.length-1)];reconnectTimer=setTimeout(()=>{reconnectTimer=null;connectWebSocket();},delay);}
function scheduleRefresh() { clearInterval(refreshTimer); refreshTimer=setInterval(refresh,state.refreshRate); save('refreshRate',state.refreshRate); }

