function installDecodedPacketLayout(){const root=$('decoded');if(!root||root.dataset.packetLayout)return;root.dataset.packetLayout='1';root.innerHTML=`<div class="section-title"><div><p class="eyebrow">Signalinterpretation</p><h2>Decoded Messages</h2><p>LIN-Pakete bearbeiten und Datenbytes für die Signaldekodierung pflegen.</p></div></div><details class="tool-group decoded-tools decodedToolsGroup" open><summary><span>Decoder-Werkzeuge</span></summary><div class="group-body"><div class="actions"><button id="decoded-add">Neue Zeile</button><button id="decoded-duplicate">Zeile duplizieren</button><button id="decoded-delete">Ausgewählte Zeile löschen</button><button id="decoded-send" class="primary">Ausgewähltes Paket senden</button><button id="decoded-clear">Liste leeren</button><span id="decoded-result"></span></div></div></details><details class="tool-group decoded-data decodedDataGroup" open><summary><span>Decoded Messages</span></summary><div class="group-body"><div class="table-wrap tall decoded-editor-wrap"><table class="decoded-editor"><thead><tr><th>ID</th><th>Label</th><th>LEN</th><th>D0</th><th>D1</th><th>D2</th><th>D3</th><th>D4</th><th>D5</th><th>D6</th><th>D7</th><th>ASCII</th><th></th></tr></thead><tbody id="decoded-list"></tbody></table></div><div id="byte-inspector" class="byte-inspector" hidden></div></div></details>`;}
function normalizeDecodedByte(value){const raw=String(value||'00').trim().toUpperCase().replace(/^0X/,'');const parsed=parseInt(raw||'0',16);return Number.isFinite(parsed)?hex(parsed&0xFF):'00';}
function decodedAscii(row){return row.bytes.slice(0,row.len).map(byte=>{const value=parseInt(byte,16);return value>=32&&value<=126?String.fromCharCode(value):'.';}).join('');}
function makeDecodedPacket(frame=null){const sourceBytes=frame?bytes(frame):[],numeric=frame?Number(frame.id):0x12,id=hex(Math.max(0,Math.min(0x3F,numeric))),len=Math.max(1,Math.min(8,Number(frame?.length||sourceBytes.length||8)));return {uid:`D${Date.now().toString(36)}${Math.random().toString(36).slice(2,7)}`,id,label:state.labels[id]||labelFor(id).replace(/^-$/,''),len,bytes:Array.from({length:8},(_,i)=>normalizeDecodedByte(sourceBytes[i]||'00'))};}
function migrateDecodedPackets(){const byId=new Map();(state.signals||[]).forEach(signal=>{const id=idKey(signal.id);if(!byId.has(id))byId.set(id,makeDecodedPacket({id:parseInt(id,16),length:8,data:'00 00 00 00 00 00 00 00'}));const row=byId.get(id);row.label=state.labels[id]||signal.name||row.label;});Object.entries(state.labels||{}).forEach(([id,label])=>{const key=idKey(id);if(!byId.has(key))byId.set(key,makeDecodedPacket({id:parseInt(key,16),length:8,data:'00 00 00 00 00 00 00 00'}));byId.get(key).label=label;});return [...byId.values()];}
function decodedPackets(){if(!Array.isArray(state.decodedRows)){const stored=load('decodedRows',null);state.decodedRows=Array.isArray(stored)?stored:migrateDecodedPackets();}return state.decodedRows;}
function saveDecodedPackets(){state.decodedRows=decodedPackets().map(row=>({...row,id:idKey(row.id),len:Math.max(1,Math.min(8,Number(row.len)||8)),bytes:Array.from({length:8},(_,i)=>normalizeDecodedByte(row.bytes?.[i]))}));state.decodedRows.forEach(row=>{if(row.label)state.labels[row.id]=row.label;});state.signals=state.signals.filter(signal=>signal.source==='LDF');state.decodedRows.forEach(row=>state.signals.push({id:row.id,name:row.label||`LIN ${row.id}`,byte:0,bit:0,length:Math.min(32,row.len*8),factor:1,offset:0,unit:'',source:'PACKET'}));save('decodedRows',state.decodedRows);save('labels',state.labels);save('signals',state.signals);}
function selectedDecodedPacket(){return decodedPackets().find(row=>row.uid===state.selectedDecodedUid);}
function renderDecodedByteInspector(){const panel=$('byte-inspector'),row=selectedDecodedPacket();if(!panel||!row){if(panel)panel.hidden=true;return;}const index=Math.max(0,Math.min(7,Number(state.selectedDecodedByte)||0)),value=parseInt(row.bytes[index]||'00',16),binary=value.toString(2).padStart(8,'0'),ascii=value>=32&&value<=126?String.fromCharCode(value):'.';panel.hidden=false;panel.innerHTML=`<span class="decodedInspectorTitle">Byte <b>D${index}</b></span><span>HEX <b>${hex(value)}</b></span><span>DEC <b>${value}</b></span><span>Signed <b>${value>127?value-256:value}</b></span><span>BIN <b>${binary}</b></span><span>ASCII <b>${esc(ascii)}</b></span><span class="decodedInspectorBits">${binary.split('').map((bit,i)=>`<span class="decodedBit ${bit==='1'?'on':''}">b${7-i}:${bit}</span>`).join('')}</span>`;}
renderDecoded=function(){if(document.activeElement?.matches('[data-decoded-field]'))return;installDecodedPacketLayout();const rows=decodedPackets();$('decoded-list').innerHTML=rows.length?rows.map(row=>`<tr class="${state.selectedDecodedUid===row.uid?'selected-row':''}" data-decoded-uid="${row.uid}"><td><input class="decoded-input id-input" data-decoded-field="id" value="${displayId(row.id)}"></td><td><input class="decoded-input label-input" data-decoded-field="label" value="${esc(row.label||'')}"></td><td><select class="decoded-input dlc-input" data-decoded-field="len">${Array.from({length:8},(_,i)=>`<option value="${i+1}" ${row.len===i+1?'selected':''}>${i+1}</option>`).join('')}</select></td>${Array.from({length:8},(_,i)=>`<td class="decodedByteCell ${state.selectedDecodedUid===row.uid&&state.selectedDecodedByte===i?'selectedDecodedByte':''}"><input class="decoded-input byte-input" data-decoded-field="byte" data-byte="${i}" value="${byteDisplay(row.bytes[i]||'00')}" maxlength="4"></td>`).join('')}<td class="decoded-ascii">${esc(decodedAscii(row))}</td><td><button class="icon danger" data-decoded-delete="${row.uid}">×</button></td></tr>`).join(''):emptyRow(13,'Noch keine Decoded-Pakete definiert.');renderDecodedByteInspector();updateIdFormatUi();};
function updateDecodedPacketField(input){const row=input.closest('[data-decoded-uid]'),packet=row&&decodedPackets().find(item=>item.uid===row.dataset.decodedUid);if(!packet)return;state.selectedDecodedUid=packet.uid;const field=input.dataset.decodedField;if(field==='id'){const value=parseDisplayId(input.value);if(!Number.isFinite(value)||value<0||value>0x3F){input.classList.add('input-invalid');return;}packet.id=hex(value);input.classList.remove('input-invalid');}else if(field==='label'){packet.label=input.value.trim();if(packet.label)state.labels[packet.id]=packet.label;}else if(field==='len')packet.len=Math.max(1,Math.min(8,Number(input.value)||8));else if(field==='byte'){const index=Number(input.dataset.byte)||0;packet.bytes[index]=normalizeDecodedByte(input.value);state.selectedDecodedByte=index;}saveDecodedPackets();renderOverview();renderLabels();}
installDecodedPacketLayout();
document.addEventListener('input',e=>{if(e.target.closest('[data-decoded-field]'))updateDecodedPacketField(e.target);});document.addEventListener('change',e=>{if(e.target.closest('[data-decoded-field]')){updateDecodedPacketField(e.target);renderDecoded();}});
function bindDecodedPacketActions(){
  $('decoded-add').onclick=()=>{const row=makeDecodedPacket();decodedPackets().push(row);state.selectedDecodedUid=row.uid;state.selectedDecodedByte=0;saveDecodedPackets();renderDecoded();};
  $('decoded-duplicate').onclick=()=>{const row=selectedDecodedPacket();if(!row)return toast('Zuerst eine Zeile auswählen','error');const copy={...row,uid:`D${Date.now().toString(36)}${Math.random().toString(36).slice(2,7)}`,label:row.label?`${row.label} Kopie`:'Kopie',bytes:[...row.bytes]};const rows=decodedPackets(),index=rows.findIndex(item=>item.uid===row.uid);rows.splice(index+1,0,copy);state.selectedDecodedUid=copy.uid;saveDecodedPackets();renderDecoded();};
  $('decoded-delete').onclick=()=>{const rows=decodedPackets(),index=rows.findIndex(row=>row.uid===state.selectedDecodedUid);if(index<0)return toast('Zuerst eine Zeile auswählen','error');rows.splice(index,1);state.selectedDecodedUid=rows[Math.min(index,rows.length-1)]?.uid||null;saveDecodedPackets();renderDecoded();renderOverview();};
  $('decoded-clear').onclick=async()=>{if(!decodedPackets().length)return;if(!await askConfirm('Decoded-Liste wirklich leeren?','Decoded-Liste leeren'))return;state.decodedRows=[];state.selectedDecodedUid=null;saveDecodedPackets();renderDecoded();renderOverview();toast('Decoded-Liste geleert','success');};
  $('decoded-send').onclick=async()=>{const row=selectedDecodedPacket();if(!row)return toast('Keine Zeile ausgewählt','error');loadFrameIntoTx({id:parseInt(row.id,16),length:row.len,data:row.bytes.slice(0,row.len).join(' ')});await sendTxFrame();$('decoded-result').textContent=`ID ${displayId(row.id)} gesendet`;};
}
function initializeDecodedPackets(){installDecodedPacketLayout();bindDecodedPacketActions();renderDecoded();}
initializeDecodedPackets();

function cancelPendingHardwareSource(source){if(hardwareSendPending?.source===source)hardwareSendPending=null;}
function stopSimulator(){state.simTimers.forEach(clearInterval);state.simTimers=[];state.simRunning=false;cancelPendingHardwareSource('simulator');renderSimulator();}
async function sendHardwareFrame(source,id,values){if(!sourceMayTransmit(source))return false;hardwareSendPending={source,id,values:[...values]};if(hardwareSendBusy)return true;hardwareSendBusy=true;try{while(hardwareSendPending&&sourceMayTransmit(hardwareSendPending.source)){const frame=hardwareSendPending;hardwareSendPending=null;const response=await fetch('/api/send',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:new URLSearchParams({id:hex(frame.id),data:frame.values.join(' '),checksum:'auto'})});if(!response.ok)throw Error(await response.text());hardwareSendErrorShown=false;}return true;}catch{hardwareSendPending=null;if(!hardwareSendErrorShown){hardwareSendErrorShown=true;toast('LIN-Hardware-Senden fehlgeschlagen','error');}return false;}finally{hardwareSendBusy=false;}}
function startSimulator(){stopSimulator(); const active=state.simulator.filter(s=>s.active); if(!active.length)return toast('Kein aktiver Simulator-Frame','error'); state.simRunning=true; active.forEach(item=>state.simTimers.push(setInterval(()=>{item.count=(item.count||0)+1; const values=item.data.trim().split(/\s+/).filter(Boolean); if(/counter|zähler/i.test(item.label||'')){values[0]=hex((item.counter||0)&255);item.counter=((item.counter||0)+1)&255;} const data=values.join(' '); const id=parseInt(item.id,16); ingest([{sequence:-(++state.simSequence),time:performance.now(),id,pid:linPid(id),length:values.length,data,checksum:'--',checksumType:'classic',valid:true}],'SIM');sendHardwareFrame('simulator',id,values);queueRender();},Math.max(20,item.interval)))); renderSimulator(); toast(sourceMayTransmit('simulator')?'LIN-Hardware-Simulator gestartet':'Browser-Simulator gestartet','success');}
$('sim-toggle').onclick=()=>state.simRunning?stopSimulator():startSimulator();
$('sim-byte-editor').innerHTML=Array.from({length:8},(_,i)=>`<label>D${i}<input data-sim-byte="${i}" data-hex-input maxlength="4" value="${byteDisplay(parseInt(['00','11','22','33','44','55','66','77'][i],16))}"></label>`).join('');['sim-id','sim-dlc'].forEach(id=>$(id).addEventListener(id==='sim-dlc'?'change':'input',updateSimPreview));$('sim-byte-editor').addEventListener('input',updateSimPreview);
$('sim-add').onclick=()=>{const numeric=parseDisplayId($('sim-id').value),id=Number.isFinite(numeric)?hex(numeric):'',values=simValues(),data=values.join(' ');if(!Number.isFinite(numeric)||numeric<0||numeric>0x3F||values.some(x=>!/^[0-9A-F]{2}$/.test(x)))return toast('ID oder Daten ungültig','error');state.simulator.push({id,label:$('sim-label').value.trim()||'Simulator',dlc:values.length,data,interval:Number($('sim-interval').value)||500,active:true,count:0});save('simulator',state.simulator);restartSimulatorIfRunning();renderSimulator();};
$('sim-example').onclick=()=>{state.simulator=[{id:'12',label:'Counter',data:'00 11 22 33 44 55 66 77',interval:500,active:true,count:0},{id:'21',label:'Status',data:'01 00 FF',interval:1000,active:true,count:0}];save('simulator',state.simulator);renderSimulator();};
$('sim-clear').onclick=()=>{stopSimulator();state.simulator=[];save('simulator',state.simulator);renderSimulator();};

function linPid(id){id&=0x3F;const p0=((id>>0)^(id>>1)^(id>>2)^(id>>4))&1,p1=(~((id>>1)^(id>>3)^(id>>4)^(id>>5)))&1;return id|(p0<<6)|(p1<<7);}
function generatorConfig(){const min=parseDisplayId($('generator-id-min').value),max=parseDisplayId($('generator-id-max').value),rate=Math.max(1,Math.min(500,Number($('generator-rate').value)||20)),dlcText=$('generator-dlc').value,step=Math.max(1,Math.min(255,Number($('generator-step').value)||1)),period=Math.max(2,Number($('generator-period').value)||32),start=Math.max(0,Math.min(255,Number($('generator-start').value)||0)),target=Math.max(0,Math.min(7,Number($('generator-byte').value)||0)),seed=parseInt($('generator-seed').value,16)||0xACE1,baseText=$('generator-base-data').value.replace(/[^0-9A-F]/gi,'').toUpperCase(),base=(baseText.match(/../g)||[]).slice(0,8).map(x=>parseInt(x,16));while(base.length<8)base.push(0);if(!Number.isFinite(min)||!Number.isFinite(max)||min<0||max>0x3F||min>max)return null;return{min,max,rate,dlcText,step,period,start,target,seed:seed&0xFFFF,base,type:$('generator-type').value};}
function generatedBytes(cfg,dlc,id){const data=cfg.base.slice(0,dlc),selected=[...document.querySelectorAll('[data-generator-mask]:checked')].map(x=>Number(x.dataset.generatorMask)).filter(i=>i<dlc);if(!selected.length)selected.push(0);const target=selected.includes(Math.min(dlc-1,cfg.target))?Math.min(dlc-1,cfg.target):selected[0],g=state.generatorState;if(cfg.type==='counter'){const value=g.counter&255;selected.forEach(i=>data[i]=value);g.counter=(g.counter+cfg.step)&255;}else if(cfg.type==='runningbit'){const position=g.bit++%(selected.length*8);selected.forEach(i=>data[i]=0);data[selected[Math.floor(position/8)]]=1<<(position%8);}else if(cfg.type==='sine'){data[target]=Math.round(127.5+127.5*Math.sin((g.frame%cfg.period)*2*Math.PI/cfg.period));g.frame++;}else if(cfg.type==='saw'){data[target]=g.counter&255;g.counter=(g.counter+cfg.step)&255;}else if(cfg.type==='square'){data[target]=(g.frame%cfg.period)<cfg.period/2?0:255;g.frame++;}else if(cfg.type==='lfsr'){selected.forEach(i=>{let value=g.lfsr&0xFFFF;value=(value>>1)^((-(value&1))&0xB400);g.lfsr=value||cfg.seed;data[i]=value&255;});}else{const next=(g.randomById.get(id)||cfg.base).slice(),order=selected.slice().sort(()=>Math.random()-.5),maxChanges=Math.max(1,selected.length-1),changes=1+Math.floor(Math.random()*maxChanges);order.slice(0,changes).forEach(i=>next[i]=Math.floor(Math.random()*256));g.randomById.set(id,next);return next.slice(0,dlc);}return data;}
function emitGeneratedFrame(){const cfg=generatorConfig();if(!cfg){stopGenerator();return toast('Generator-ID-Bereich ungültig','error');}const dlc=cfg.dlcText==='random'?1+Math.floor(Math.random()*8):Number(cfg.dlcText),id=cfg.min+Math.floor(Math.random()*(cfg.max-cfg.min+1)),data=generatedBytes(cfg,dlc,id),values=data.map(hex),text=values.join(' ');ingest([{sequence:-(++state.simSequence),time:performance.now(),id,pid:linPid(id),length:dlc,data:text,checksum:'--',checksumType:'classic',valid:true}],'GEN');sendHardwareFrame('generator',id,values);state.generatorCount++;queueRender();if(cfg.rate!==state.generatorRate){state.generatorRate=cfg.rate;clearInterval(state.generatorTimer);state.generatorTimer=setInterval(emitGeneratedFrame,Math.max(2,1000/cfg.rate));}}
function resetGeneratorState(){const cfg=generatorConfig()||{start:0,seed:0xACE1};state.generatorState={counter:cfg.start,bit:0,frame:0,lfsr:cfg.seed,randomById:new Map()};state.generatorCount=0;}
function startGenerator(){stopGenerator();const cfg=generatorConfig();if(!cfg)return toast('Generator-ID-Bereich ungültig','error');resetGeneratorState();state.generatorRunning=true;state.generatorRate=cfg.rate;state.generatorTimer=setInterval(emitGeneratedFrame,Math.max(2,1000/cfg.rate));renderSimulator();toast(sourceMayTransmit('generator')?'LIN-Hardware-Generator gestartet':'Browser-Generator gestartet','success');}
function stopGenerator(){clearInterval(state.generatorTimer);state.generatorTimer=null;state.generatorRunning=false;cancelPendingHardwareSource('generator');renderSimulator();}
$('generator-toggle').onclick=()=>state.generatorRunning?stopGenerator():startGenerator();$('generator-reset').onclick=()=>{resetGeneratorState();renderSimulator();};

function stopReplay(){clearTimeout(state.replayTimer);state.replayTimer=null;state.replayRunning=false;cancelPendingHardwareSource('replay');renderSimulator();}
function emitReplayFrame(){const frames=replayFrames();if(!frames.length){stopReplay();return toast('Kein Log für die Wiedergabe','error');}if(state.replayPosition>=frames.length){if($('replay-loop').value==='loop')state.replayPosition=0;else{return stopReplay();}}const original=frames[state.replayPosition],frame={...original,sequence:-(++state.simSequence),time:performance.now()},id=typeof original.id==='string'?parseInt(original.id.replace(/^0x/i,''),16):Number(original.id),values=bytes(original).slice(0,Number(original.length)||8);ingest([frame],'REPLAY');if(Number.isFinite(id)&&id>=0&&id<=0x3F)sendHardwareFrame('replay',id,values);state.replayPosition++;queueRender();if(state.replayRunning){const next=frames[state.replayPosition],speed=Number($('replay-speed').value)||1,delay=next?Math.max(2,(Number(next.time)-Number(original.time))/speed):10;state.replayTimer=setTimeout(emitReplayFrame,Math.min(delay,5000));}}
function startReplay(){stopReplay();if(!replayFrames().length)return toast('Kein Log für die Wiedergabe','error');if(state.replayPosition>=replayFrames().length)state.replayPosition=0;state.replayRunning=true;emitReplayFrame();renderSimulator();toast(sourceMayTransmit('replay')?'LIN-Hardware-Log-Wiedergabe gestartet':'Browser-Log-Wiedergabe gestartet','success');}
$('replay-toggle').onclick=()=>state.replayRunning?stopReplay():startReplay();$('replay-step').onclick=()=>{stopReplay();emitReplayFrame();};$('replay-source').onchange=()=>{stopReplay();state.replayPosition=0;renderSimulator();};

