function installTxLayout(){const root=$('tx');if(!root||root.dataset.txLayout)return;root.dataset.txLayout='1';root.innerHTML=`<div class="section-title"><div><p class="eyebrow">LIN Master</p><h2>TX</h2><p>LIN-Frames vorbereiten, prüfen und senden.</p></div><span id="tx-mode-status" class="safety-lock safe">Browser · kein LIN-TX</span></div><details class="tool-group tx-tools" open><summary><span>TX-Werkzeuge</span></summary><div class="group-body"><div class="actions"><button id="tx-send" class="primary">Senden</button><button id="tx-cycle">Zyklisch senden</button><span id="tx-result"></span></div></div></details><details class="tool-group tx-data" open><summary><span>LIN-TX</span></summary><div class="group-body"><div class="form-grid tx-grid"><label>ID<input id="tx-id" data-hex-input value="0x12" maxlength="6"></label><label>LEN<select id="tx-dlc">${Array.from({length:8},(_,i)=>`<option value="${i+1}" ${i===7?'selected':''}>${i+1}</option>`).join('')}</select></label><label>Checksumme<select id="tx-checksum"><option value="auto" selected>Auto</option><option value="classic">Classic</option><option value="enhanced">Enhanced</option></select></label><label>Intervall [ms]<input id="tx-interval" type="number" min="20" value="100"></label></div><div id="tx-byte-editor" class="sim-byte-editor tx-byte-editor">${Array.from({length:8},(_,i)=>`<label>D${i}<input data-tx-byte="${i}" data-hex-input maxlength="2" value="00"></label>`).join('')}</div><div class="sim-preview">Vorschau: <code id="tx-preview"></code></div><div class="table-wrap sim-table tx-history-table"><table><thead><tr><th>Zeit</th><th>ID</th><th>PID</th><th>LEN</th><th>Daten</th><th>Checksumme</th></tr></thead><tbody id="tx-history"></tbody></table></div></div></details>`;}
function updateTxLock(enabled=latestStatus.listenOnly===false){const allowed=enabled&&txSources.tx,summary=$('tx-lock-summary');if(summary)summary.textContent=allowed?'AKTIV':'GESPERRT';const toggle=$('lin-mode-toggle');if(toggle){toggle.textContent=enabled?'Listen Only aktivieren':'TX aktivieren';toggle.classList.toggle('danger',enabled);}$('tx-send')?.classList.toggle('danger',!allowed);$('tx-cycle')?.classList.toggle('danger',!allowed);}
function txBytes(){const dlc=Number($('tx-dlc')?.value)||8;return [...document.querySelectorAll('[data-tx-byte]')].slice(0,dlc).map(input=>normalizeDecodedByte(input.value));}
function updateTxPreview(){if(!$('tx-preview'))return;const raw=$('tx-id').value.trim(),numeric=parseDisplayId(raw),id=Number.isFinite(numeric)?displayId(numeric):raw.replace(/^0X/i,'0x');$('tx-preview').textContent=`${id}  ${txBytes().join(' ')}`;document.querySelectorAll('[data-tx-byte]').forEach((input,index)=>input.disabled=index>=Number($('tx-dlc').value));}
function linChecksumJs(data,pid,enhanced){let sum=enhanced?pid:0;data.forEach(byte=>{sum+=parseInt(byte,16)||0;if(sum>0xFF)sum-=0xFF;});return hex((~sum)&0xFF);}
async function sendTxFrame(){if(!sourceMayTransmit('tx'))return toast('TX-Tab ist in den Einstellungen nicht als Sendequelle freigegeben','error');const numeric=parseDisplayId($('tx-id').value),id=Number.isFinite(numeric)?hex(numeric):'',data=txBytes(),checksumMode=$('tx-checksum').value;if(!Number.isFinite(numeric)||numeric<0||numeric>0x3F)return toast('LIN-ID ungültig','error');try{const body=new URLSearchParams({id,data:data.join(' '),checksum:checksumMode});const response=await fetch('/api/send',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body});if(!response.ok)throw Error(await response.text());const result=await response.json(),pid=Number(result.pid||linPid(numeric)),enhanced=result.checksumType==='enhanced',checksum=linChecksumJs(data,pid,enhanced);$('tx-result').textContent=`ID ${displayId(numeric)} gesendet`;$('tx-history').insertAdjacentHTML('afterbegin',`<tr><td>${new Date().toLocaleTimeString('de-DE')}</td><td>${displayId(numeric)}</td><td>${hex(pid)}</td><td>${data.length}</td><td class="payload">${data.join(' ')}</td><td>${checksum} <small>${enhanced?'E':'C'}</small></td></tr>`);ingest([{sequence:-(++state.simSequence),time:performance.now(),id:numeric,pid,length:data.length,data:data.join(' '),checksum,checksumType:enhanced?'enhanced':'classic',valid:true}],'TX');queueRender();toast(`LIN ${displayId(numeric)} gesendet`,'success');}catch{toast('LIN-Frame konnte nicht gesendet werden','error');}}
installTxLayout();updateTxLock();updateTxPreview();$('tx-send').onclick=sendTxFrame;$('tx-cycle').onclick=()=>{if(state.txTimer){clearInterval(state.txTimer);state.txTimer=null;$('tx-cycle').classList.remove('active');$('tx-cycle').textContent='Zyklisch senden';toast('Zyklisches Senden gestoppt','success');return;}if(!sourceMayTransmit('tx'))return toast('TX-Tab ist in den Einstellungen nicht als Sendequelle freigegeben','error');state.txTimer=setInterval(sendTxFrame,Math.max(20,Number($('tx-interval').value)||100));$('tx-cycle').classList.add('active');$('tx-cycle').textContent='Zyklisch stoppen';toast('Zyklisches Senden gestartet','success');};$('tx').addEventListener('input',updateTxPreview);$('tx').addEventListener('change',updateTxPreview);

const txSourceBox=document.createElement('div');txSourceBox.className='tx-source-settings';txSourceBox.innerHTML='<span>Hardware-TX-Quellen</span><div><label><input data-tx-source="tx" type="checkbox"> TX-Tab</label><label><input data-tx-source="generator" type="checkbox"> Generator</label><label><input data-tx-source="simulator" type="checkbox"> Simulator</label><label><input data-tx-source="replay" type="checkbox"> Log-Wiedergabe</label></div><small>Nur markierte Quellen dürfen bei aktiviertem LIN-TX auf den Bus senden.</small>';$('lin-mode-toggle').closest('.setting-row').after(txSourceBox);txSourceBox.querySelectorAll('[data-tx-source]').forEach(input=>{const source=input.dataset.txSource;input.checked=txSources[source]===true;input.onchange=()=>{txSources[source]=input.checked;save('txSources',txSources);if(!input.checked)cancelPendingHardwareSource(source);if(source==='tx'&&!input.checked&&state.txTimer){clearInterval(state.txTimer);state.txTimer=null;$('tx-cycle').classList.remove('active');$('tx-cycle').textContent='Zyklisch senden';}updateLiveSourceUi();toast(`${input.parentElement.textContent.trim()}: Hardware-TX ${input.checked?'erlaubt':'gesperrt'}`,'success');};});

$('setting-id-format').value=load('idFormat','HEX');normalizeInitialIdFields();updateIdFormatUi();$('setting-id-format').onchange=e=>{const old=load('idFormat','HEX'),next=e.target.value,fields=['filter-id-from','filter-id-to','filter-include-ids','filter-exclude-ids','label-id','sim-id','generator-id-min','generator-id-max','server-filter-ids'];fields.forEach(id=>{const input=$(id);if(!input||!input.value.trim())return;input.value=input.value.replace(/0X[0-9A-F]+|[0-9A-F]+H?|\d+/gi,token=>{let n;if(/^0X/i.test(token))n=parseInt(token.slice(2),16);else if(/H$/i.test(token))n=parseInt(token.slice(0,-1),16);else n=parseInt(token,old==='DEC'?10:16);return Number.isFinite(n)?(next==='DEC'?String(n):hexDisplay(n)):token;});});save('idFormat',next);updateIdFormatUi();renderAll();toast(`ID-Anzeige: ${next}`,'success');};
async function updateLinSettings(extra,message){try{const response=await fetch('/api/lin',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:new URLSearchParams(extra)});if(!response.ok)throw Error();applyStatus(await response.json());toast(message,'success');}catch{toast('LIN-Einstellung konnte nicht geändert werden','error');}}
$('setting-baud').onchange=e=>updateLinSettings({baudrate:e.target.value},'LIN-Baudrate geändert');$('setting-checksum').onchange=e=>updateLinSettings({checksum:e.target.value},'Checksumme geändert');$('lin-mode-toggle').onclick=()=>{const enabled=latestStatus.listenOnly===false;updateLinSettings({mode:enabled?'listen':'normal'},enabled?'Listen Only aktiviert':'LIN-TX aktiviert');};
async function loadWifiSettings(){try{const response=await fetch('/api/wifi',{cache:'no-store'});if(!response.ok)throw Error();const wifi=await response.json();if(document.activeElement!==$('wifi-ssid'))$('wifi-ssid').value=wifi.ssid||'';$('wifi-password').value='';$('wifi-password').placeholder=wifi.passwordStored?'Gespeichert · leer lassen zum Beibehalten':'WLAN-Passwort';$('wifi-sta-status').textContent=wifi.connected?`Verbunden · ${wifi.ip}`:wifi.ssid?'Konfiguriert · nicht verbunden':'Nicht konfiguriert';}catch{$('wifi-sta-status').textContent='ESP32 nicht erreichbar';}}
$('wifi-save').onclick=async()=>{const ssid=$('wifi-ssid').value.trim(),password=$('wifi-password').value;if(ssid.length>32||password.length>64)return toast('SSID oder Passwort ist zu lang','error');try{const response=await fetch('/api/wifi',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:new URLSearchParams({ssid,password})});if(!response.ok)throw Error();applyStatus(await response.json());await loadWifiSettings();toast(ssid?'WLAN gespeichert · Verbindung wird aufgebaut':'WLAN-Verbindung entfernt','success');}catch{toast('WLAN-Einstellung konnte nicht gespeichert werden','error');}};
$('wifi-clear').onclick=()=>{$('wifi-ssid').value='';$('wifi-password').value='';$('wifi-save').click();};
$('server-filter-apply').onclick=async()=>{const active=$('server-filter-apply').dataset.active==='1',values=active?'':$('server-filter-ids').value.split(/[\s,;]+/).filter(Boolean).map(value=>{const id=parseDisplayId(value);return Number.isFinite(id)?hex(id):'';}).filter(Boolean).join(' ');if(!active&&!values)return toast('Mindestens eine LIN-ID eingeben','error');try{const body=new URLSearchParams({mode:$('server-filter-mode').value,ids:values});const response=await fetch('/api/filter',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body});if(!response.ok)throw Error();applyStatus(await response.json());toast(active?'Serverfilter gelöscht':'Serverfilter angewendet','success');}catch{toast('Serverfilter konnte nicht angewendet werden','error');}};
function parseLdf(text,name){const signalSizes=new Map(),signalsBlock=text.match(/Signals\s*\{([\s\S]*?)\n\}/i)?.[1]||'';for(const match of signalsBlock.matchAll(/([A-Za-z_]\w*)\s*:\s*(\d+)\s*,/g))signalSizes.set(match[1],Math.max(1,Math.min(32,Number(match[2]))));const imported=[];for(const frame of text.matchAll(/([A-Za-z_]\w*)\s*:\s*(0x[0-9A-F]+|\d+)\s*,\s*[A-Za-z_]\w*\s*,\s*(\d+)\s*\{([^}]*)\}/gi)){const numeric=/^0x/i.test(frame[2])?parseInt(frame[2],16):Number(frame[2]);if(!Number.isFinite(numeric)||numeric<0||numeric>0x3F)continue;const id=hex(numeric);if(!state.labels[id])state.labels[id]=frame[1];for(const placement of frame[4].matchAll(/([A-Za-z_]\w*)\s*,\s*(\d+)\s*;/g)){const offset=Number(placement[2]),length=signalSizes.get(placement[1])||1;imported.push({id,name:placement[1],byte:Math.floor(offset/8),bit:offset%8,length,factor:1,offset:0,unit:'',source:'LDF',ldf:name});}}state.signals=state.signals.filter(signal=>signal.source!=='LDF').concat(imported);save('labels',state.labels);save('signals',state.signals);renderAll();$('ldf-status').textContent=`${name}: ${new Set(imported.map(x=>x.id)).size} Frames, ${imported.length} Signale geladen.`;return imported.length;}
const LDF_MAX_SIZE=256*1024;
async function activateLdf(name,text=null){if(!$('ldf-enabled').checked||!name){state.signals=state.signals.filter(signal=>signal.source!=='LDF');save('signals',state.signals);renderAll();$('ldf-status').textContent=name?'LDF deaktiviert.':'Keine LDF geladen.';return;}try{if(text===null){const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),10000);let response;try{response=await fetch(`/api/ldf/file?name=${encodeURIComponent(name)}`,{cache:'no-store',signal:controller.signal});}finally{clearTimeout(timeout);}if(!response.ok)throw Error(`HTTP ${response.status}`);const size=Number(response.headers.get('content-length')||0);if(size>LDF_MAX_SIZE)throw Error('Datei zu groß');text=await response.text();}if(new Blob([text]).size>LDF_MAX_SIZE)throw Error('Datei zu groß');save('activeLdf',name);parseLdf(text,name);}catch(error){const reason=error?.name==='AbortError'?'Zeitüberschreitung':String(error?.message||error);$('ldf-status').textContent=`LDF konnte nicht gelesen werden: ${reason}`;toast('LDF konnte nicht aktiviert werden','error');}}
const ldfSelectRow=$('ldf-select').closest('.setting-row'),ldfToggle=document.createElement('label');ldfToggle.className='ldf-enable';ldfToggle.innerHTML='<input id="ldf-enabled" type="checkbox"> LDF verwenden';ldfSelectRow.before(ldfToggle);$('ldf-enabled').checked=load('ldfEnabled',false);$('ldf-enabled').onchange=()=>{save('ldfEnabled',$('ldf-enabled').checked);activateLdf($('ldf-select').value);};$('ldf-select').onchange=()=>activateLdf($('ldf-select').value);
async function loadLdfList(){try{const response=await fetch('/api/ldf',{cache:'no-store'});if(!response.ok)throw Error();const data=await response.json(),select=$('ldf-select'),active=load('activeLdf',''),files=(data.files||[]).map(entry=>typeof entry==='string'?{name:entry,size:0}:entry);select.innerHTML='<option value="">Keine LDF vorhanden</option>'+files.map(file=>`<option value="${esc(file.name)}" ${file.name===active?'selected':''}>${esc(file.name)}${file.size?` · ${Math.ceil(file.size/1024)} kB`:''}</option>`).join('');$('ldf-status').textContent=files.length?`${files.length} LDF-Datei(en) vorhanden · max. ${Math.floor(Number(data.maxSize||LDF_MAX_SIZE)/1024)} kB`:'Keine LDF geladen.';if($('ldf-enabled').checked&&select.value)activateLdf(select.value);}catch{$('ldf-status').textContent='ESP32 nicht erreichbar.';}}
$('ldf-reload').onclick=loadLdfList;$('ldf-upload').onchange=async e=>{const file=e.target.files[0];if(!file)return;const text=await file.text(),form=new FormData();form.append('file',file);try{const response=await fetch('/api/ldf/upload',{method:'POST',body:form});if(!response.ok)throw Error();save('activeLdf',file.name);save('ldfEnabled',true);$('ldf-enabled').checked=true;await loadLdfList();parseLdf(text,file.name);toast('LDF gespeichert und aktiviert','success');}catch{toast('LDF konnte nicht gespeichert werden','error');}};$('ldf-delete').onclick=async()=>{const name=$('ldf-select').value;if(!name)return toast('Keine LDF ausgewählt','error');if(!await askConfirm(`${name} wirklich löschen?`,'LDF löschen'))return;try{const response=await fetch(`/api/ldf?name=${encodeURIComponent(name)}`,{method:'DELETE'});if(!response.ok)throw Error();if(load('activeLdf','')===name){save('activeLdf','');state.signals=state.signals.filter(signal=>signal.source!=='LDF');save('signals',state.signals);}await loadLdfList();renderAll();toast('LDF gelöscht','success');}catch{toast('LDF konnte nicht gelöscht werden','error');}};
$('ldf-upload').addEventListener('change',e=>{const file=e.target.files[0];if(!file)return;if(!/\.ldf$/i.test(file.name)||file.size>LDF_MAX_SIZE){e.stopImmediatePropagation();e.target.value='';toast(!/\.ldf$/i.test(file.name)?'Bitte eine LDF-Datei auswählen':'LDF ist größer als 256 kB','error');}},true);
const diagnosticGrid=$('diag-queue').closest('.diagnostic-grid');diagnosticGrid.insertAdjacentHTML('beforeend','<span>Heap Minimum</span><b id="diag-min-heap">—</b><span>Letztes WS-Paket vor</span><b id="diag-last-ws">—</b>');const diagnosticEventsButton=document.createElement('button');diagnosticEventsButton.id='diag-events';diagnosticEventsButton.textContent='Ereignisse anzeigen';$('diag-reset').before(diagnosticEventsButton);const diagnosticEventsBox=document.createElement('pre');diagnosticEventsBox.id='diag-events-list';diagnosticEventsBox.hidden=true;$('diag-result').after(diagnosticEventsBox);diagnosticEventsButton.onclick=()=>{diagnosticEventsBox.hidden=!diagnosticEventsBox.hidden;diagnosticEventsBox.textContent=diagnosticEvents.map(item=>`${new Date(item.at).toLocaleTimeString('de-DE')}  ${item.text}`).join('\n')||'Keine Diagnose-Ereignisse vorhanden.';};
$('diag-selftest').onclick=()=>{const checks=[['WebSocket',socketOpen],['Queue',Number(latestStatus.queueDrops||0)===0],['Speicher',Number(latestStatus.freeHeap||0)>20000],['Parser',latestStatus.parser==='validated-passive']];$('diag-result').textContent=checks.map(([name,ok])=>`${ok?'✔':'⚠'} ${name}`).join(' · ');recordDiagnostic(`Selbsttest: ${checks.every(x=>x[1])?'OK':'Warnung'}`);};$('diag-reset').onclick=async()=>{try{const response=await fetch('/api/diagnostics/reset',{method:'POST'});if(!response.ok)throw Error();minFreeHeap=Number((await response.clone().json()).freeHeap||0);applyStatus(await response.json());recordDiagnostic('Diagnose-Spitzenwerte zurückgesetzt');toast('Spitzenwerte zurückgesetzt','success');}catch{toast('Spitzenwerte konnten nicht zurückgesetzt werden','error');}};
setInterval(()=>{if(state.logActive)flushLog();if(state.overviewChanged)renderOverview();if(socketOpen&&lastWsMessageAt&&Date.now()-lastWsMessageAt>8000){connectionGeneration++;socketOpen=false;setConnection(false);try{socket.close();}catch{}scheduleReconnect();}},1000);window.addEventListener('beforeunload',e=>{if(state.logActive){flushLog();e.preventDefault();e.returnValue='';}});
document.addEventListener('visibilitychange',()=>{if(document.hidden){clearTimeout(reconnectTimer);reconnectTimer=null;return;}if(!socket||socket.readyState!==WebSocket.OPEN){connectionGeneration++;connectWebSocket();}else{lastWsMessageAt=Date.now();loadSnapshot();}renderAll();});

renderDecoded();renderLabels();renderAll();restoreLog();loadLdfList();loadWifiSettings();loadSnapshot();connectWebSocket();scheduleRefresh();
